
#!/usr/bin/env bash 
# ============================================================================== 
# UserPromptSubmit Hook: ルール検知・プロンプト注入・セッション計測 
# ============================================================================== 
set -euo pipefail HOOK\_DIR="$(cd "$(dirname "${BASH\_SOURCE[0]}")" &amp;&amp; pwd)" BASE\_DIR="$(cd "${HOOK\_DIR}/.." &amp;&amp; pwd)" RULES\_FILE="${BASE\_DIR}/rules.jsonl" METRICS\_FILE="${BASE\_DIR}/rule\_metrics.json" USER\_INPUT=$(cat || true) if [ -z "$USER\_INPUT" ]; then exit 0 fi python3 - &lt;&lt; 'EOF' "$USER\_INPUT" "$RULES\_FILE" "$METRICS\_FILE" import sys, os, json, datetime prompt\_raw = sys.argv[1] rules\_path = sys.argv[2] metrics\_path = sys.argv[3] try: data = json.loads(prompt\_raw) prompt\_text = data.get("prompt", prompt\_raw) except Exception: prompt\_text = prompt\_raw if not os.path.exists(rules\_path): sys.exit(0) active\_rules = [] try: with open(rules\_path, "r", encoding="utf-8") as f: for line in f: line = line.strip() if not line: continue try: rule = json.loads(line) if rule.get("status", "active") == "active": active\_rules.append(rule) except Exception: continue except Exception: sys.exit(0) prompt\_lower = prompt\_text.lower() matched\_rules = [] for r in active\_rules: triggers = r.get("trigger", []) if isinstance(triggers, str): triggers = [triggers] for trig in triggers: if trig.lower() in prompt\_lower: matched\_rules.append(r) break if not matched\_rules: sys.exit(0) 
# 計測データの更新 
metrics = {"current\_session\_id": "sess\_default", "rules": {}} if os.path.exists(metrics\_path): try: with open(metrics\_path, "r", encoding="utf-8") as f: metrics = json.load(f) except Exception: pass session\_id = metrics.get("current\_session\_id", "sess\_default") rules\_metrics = metrics.setdefault("rules", {}) now\_iso = datetime.datetime.now().isoformat() for r in matched\_rules: rid = r["id"] r\_stat = rules\_metrics.setdefault(rid, { "hit\_count": 0, "session\_hits": [], "last\_triggered": None }) r\_stat["hit\_count"] += 1 if session\_id not in r\_stat["session\_hits"]: r\_stat["session\_hits"].append(session\_id) r\_stat["last\_triggered"] = now\_iso try: with open(metrics\_path, "w", encoding="utf-8") as f: json.dump(metrics, f, indent=2, ensure\_ascii=False) except Exception: pass 
# コンテキスト注入文字列の構築 
directives\_text = "\\n".join([f"- [{r['id']}] {r['directive']}" for r in matched\_rules]) injection = f""" [自律成長ルール注入 (桜井哲学 x Instinct)] 以下の学習済みルールを最優先で適用してください: {directives\_text} """ print(injection) EOF